<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\ApiKeyClient\Domain\ValueObject\Accessor\ApiKeyClientKeyAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ApiKeyClientKeyAccessor trait.
 *
 * Covers null default, string/VO assignment via withKey,
 * getKey/key accessors, and isKeyChanged with/without original.
 */
class ApiKeyClientKeyAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withKey creates a new instance with the Key set
     * from a string value, and getKey returns the primitive string.
     */
    public function testWithKeyFromString(): void
    {
        // Arrange
        $holder = new ImplWithApiKeyClientKeyAccessorUnitTest();

        // Act
        $result = $holder->withKey('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getKey());
    }
    /**
     * Asserts that withkey has access to the value object
     * from a string value, and getKey returns the primitive string.
     */
    public function testWithKeyFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithApiKeyClientKeyAccessorUnitTest();

        // Act
        $result = $holder->withKey('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->key()->value());
    }
    public function testChangedKey(): void
    {
        // Arrange
        $holder = new ImplWithApiKeyClientKeyAccessorUnitTest();
        $original = $holder->withKey( 'one');
        $same = $holder->withKey( 'one');
        $modified = $holder->withKey('other');

        // Act
        $unchanged = $holder->isKeyChanged();
        $withSame = $original->isKeyChanged( $same );
        $withDiferent = $original->isKeyChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithApiKeyClientKeyAccessorUnitTest
{
  use ApiKeyClientKeyAccessor;
}
